<!--
 * 流程实例（列表页）
 *
 * @path apps\workflow-web\src\views\instance\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 流程实例（列表页）
 * <p>消费后端契约 FlowInstanceController（src/api/flowInstance.ts，auto-generated by bash/gen-contract.py）：
 * 我的发起实例列表 instanceMy()（PageResponse 转 { items, total }），
 * 支持终止 terminate、挂起 suspend / 恢复 activate、撤回 recall、轨迹 timeline 抽屉。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';
import { Page, useYdModal } from '@ydsz/common-ui';
import { YdBadge, YdButton, YdSheet, YdSheetContent, YdTable, YdTableColumn } from '@ydsz-core/ydsz-ui';
import { YdPrompt } from '@ydsz-core/popup-ui';
import { h, ref } from 'vue';
import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { activate, instanceMy, recall, suspend, terminate, timeline } from '#/api/flowInstance';
import { batchUrge } from '#/api/flowTask';
import type { FlowInstanceVO, FlowTimelineVO } from '#/api/models';
import { $t } from '#/locales';
import { createLogger } from '@ydsz-core/shared/utils';
import FlowDiagramViewer from './components/FlowDiagramViewer.vue';

const logger = createLogger('workflow-instance');
import InstanceForm from './instance-form.vue';
defineOptions({ name: 'InstanceManagement' });

/** 流程状态标签（兼容字符串/数字取值，未知值按原始值展示） */
function statusTag(flowStatus: string | undefined) {
  const status = (flowStatus ?? '').toUpperCase();
  if (status === 'FINISHED' || status === 'COMPLETED' || status === '1') {
    return h(YdBadge, { variant: 'default' }, () => $t('wf.statusDone'));
  }
  if (status === 'SUSPENDED' || status === 'PAUSED') {
    return h(YdBadge, { variant: 'destructive' }, () => $t('wf.statusPaused'));
  }
  if (status === 'TERMINATED' || status === 'CANCELED') {
    return h(YdBadge, { variant: 'destructive' }, () => $t('wf.statusTerminated'));
  }
  if (status === 'RUNNING' || status === 'ACTIVE') {
    return h(YdBadge, { variant: 'default' }, () => $t('wf.statusRunning'));
  }
  return h(YdBadge, { variant: 'secondary' }, () => flowStatus ?? '-');
}

const gridOptions: VxeTableGridOptions<FlowInstanceVO> = {
  columns: [
    { type: 'checkbox', width: 50 },
    { type: 'seq', width: 50, title: $t('wf.seq') },
    { field: 'flowName', title: $t('wf.flowName'), width: 180 },
    { field: 'flowCode', title: $t('wf.flowCode'), width: 140 },
    { field: 'title', title: $t('wf.title'), width: 160 },
    { field: 'businessNo', title: $t('wf.businessNo'), width: 140 },
    { field: 'initiatorName', title: $t('wf.initiator'), width: 100 },
    {
      field: 'flowStatus',
      title: $t('wf.status'),
      width: 90,
      slots: { default: ({ row }) => statusTag(row.flowStatus) },
    },
    { field: 'currentNodeName', title: $t('wf.currentNode'), width: 120 },
    { field: 'startAt', title: $t('wf.startTime'), width: 170 },
    {
      field: 'action',
      title: $t('wf.action'),
      width: 260,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              YdButton,
              { size: 'sm', variant: 'link' as const, class: 'text-destructive', onClick: () => handleTerminate(row) },
              () => $t('wf.terminate'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link' as const, class: 'text-yellow-600', onClick: () => handleSuspend(row) },
              () => $t('wf.suspend'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link' as const, class: 'text-green-600', onClick: () => handleActivate(row) },
              () => $t('wf.activate'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link', onClick: () => handleRecall(row) },
              () => $t('wf.recall'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link', onClick: () => openTimeline(row) },
              () => $t('wf.timeline'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  checkboxConfig: { highlight: true },
  proxyConfig: {
    ajax: {
      query: async ({ page }, formValues) => {
        const res = await instanceMy({
          pageNum: page.currentPage,
          pageSize: page.pageSize,
          flowName: formValues.flowName,
          status: formValues.status,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'flowName',
        title: $t('wf.flowName'),
        itemRender: { name: 'YdInput', props: { placeholder: $t('wf.flowName') } },
      },
      {
        field: 'status',
        title: $t('wf.status'),
        itemRender: { name: 'YdInput', props: { placeholder: $t('wf.status') } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });
const [InstanceFormModal, instanceFormApi] = useYdModal({ connectedComponent: InstanceForm });

/**
 * 发起流程实例。
 *
 * <p>打开流程实例表单弹窗。
 */
function handleAdd() {
  instanceFormApi.open();
}

/** 终止实例（需填写终止原因） */
async function handleTerminate(row: FlowInstanceVO) {
  if (!row.id) return;
  let reason: string;
  // 步骤1：输入弹窗（用户取消直接返回）
  try {
    const promptValue = await YdPrompt<string>({
      content: $t('wf.inputTerminateReason'),
      confirmText: $t('wf.confirm'),
      cancelText: $t('wf.cancel'),
      defaultValue: '',
      componentProps: {
        placeholder: $t('wf.inputTerminateReason'),
      },
      beforeClose: ({ isConfirm, value }) => {
        if (!isConfirm) return;
        if (!value) {
          showToast.warning($t('wf.terminateReasonRequired'));
          return false;
        }
      },
    });
    reason = promptValue ?? '';
  } catch {
    logger.warn('用户取消终止流程实例操作');
    return; // 用户主动取消终止操作
  }
  // 步骤2：执行终止 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await terminate({ id: row.id }, { reason });
    showToast.success($t('wf.terminatedSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('终止流程实例失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 挂起实例 */
async function handleSuspend(row: FlowInstanceVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm(
      $t('wf.confirmSuspend', { name: row.flowName }),
      $t('wf.suspendConfirm'),
      {
        type: 'warning',
      },
    );
  } catch (error) {
    logger.warn('用户取消挂起流程实例操作', error);
    return; // 用户主动取消挂起操作
  }
  // 步骤2：执行挂起 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await suspend({ id: row.id });
    showToast.success($t('wf.suspendedSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('挂起流程实例失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 恢复（激活）实例 */
async function handleActivate(row: FlowInstanceVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm(
      $t('wf.confirmActivate', { name: row.flowName }),
      $t('wf.activateConfirm'),
      {
        type: 'warning',
      },
    );
  } catch (error) {
    logger.warn('用户取消恢复流程实例操作', error);
    return; // 用户主动取消恢复操作
  }
  // 步骤2：执行恢复 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await activate({ id: row.id });
    showToast.success($t('wf.activatedSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('恢复流程实例失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 撤回实例 */
async function handleRecall(row: FlowInstanceVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm(
      $t('wf.confirmRecall', { name: row.flowName }),
      $t('wf.recallConfirm'),
      {
        type: 'warning',
      },
    );
  } catch (error) {
    logger.warn('用户取消撤回流程实例操作', error);
    return; // 用户主动取消撤回操作
  }
  // 步骤2：执行撤回 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await recall({ id: row.id }, {});
    showToast.success($t('wf.recalledSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('撤回流程实例失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/**
 * 收集勾选行的实例 ID，未勾选时提示。
 */
function getSelectedInstanceIds(): string[] {
  const rows = gridApi.grid.getCheckboxRecords() as FlowInstanceVO[];
  const ids = rows.map((item) => item.id ?? '').filter((id) => id !== '');
  if (ids.length === 0) {
    showToast.warning($t('wf.selectInstancesFirst'));
  }
  return ids;
}

/**
 * 批量催办勾选实例的当前办理人。
 * 步骤1：确认弹窗；步骤2：调用后端 batchUrge 端点（POST /instance/batchUrge）。
 */
async function handleBatchUrge() {
  const ids = getSelectedInstanceIds();
  if (ids.length === 0) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm(
      $t('wf.confirmBatchUrge', { count: ids.length }),
      $t('wf.batchUrgeConfirm'),
      {
        type: 'warning',
      },
    );
  } catch (error) {
    logger.warn('用户取消批量催办操作', error);
    return; // 用户主动取消批量催办
  }
  // 步骤2：执行批量催办 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    const result = await batchUrge({}, ids);
    const successCount = result?.successCount ?? ids.length;
    showToast.success($t('wf.batchUrgeSuccess', { count: successCount }));
    gridApi.query();
  } catch (error) {
    logger.warn('批量催办失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 轨迹抽屉状态 */
const timelineVisible = ref(false);
const timelineLoading = ref(false);
const timelineRows = ref<FlowTimelineVO[]>([]);
const timelineInstance = ref<FlowInstanceVO | null>(null);

/** 查看流程运行轨迹 */
async function openTimeline(row: FlowInstanceVO) {
  if (!row.id) return;
  timelineVisible.value = true;
  timelineLoading.value = true;
  timelineInstance.value = row;
  try {
    timelineRows.value = (await timeline({ id: row.id })) ?? [];
  } finally {
    timelineLoading.value = false;
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid :table-title="$t('wf.flowInstances')">
      <template #toolbar-tools>
        <YdButton @click="handleAdd">{{ $t('wf.startFlow') }}</YdButton>
        <YdButton variant="secondary" @click="handleBatchUrge">{{
          $t('wf.batchUrge')
        }}</YdButton>
      </template>
    </Grid>
    <InstanceFormModal @success="gridApi.query()" />
    <YdSheet :open="timelineVisible" @update:open="timelineVisible = $event">
      <YdSheetContent class="!max-w-[900px]">
      <div class="drawer-content">
        <!-- 流程图高亮 -->
        <FlowDiagramViewer :instance="timelineInstance" />
        <!-- 轨迹表格 -->
        <YdTable :data="timelineRows" border size="small" loading="timelineLoading" class="mt-4">
          <YdTableColumn prop="type" :label="$t('wf.type')" width="100" />
          <YdTableColumn prop="timestamp" :label="$t('wf.timestamp')" width="170" />
          <YdTableColumn prop="nodeName" :label="$t('wf.node')" width="120" />
          <YdTableColumn prop="assigneeName" :label="$t('wf.assigneeName')" width="100" />
          <YdTableColumn prop="action" :label="$t('wf.action')" width="100" />
          <YdTableColumn
            prop="comment"
            :label="$t('wf.comment')"
            min-width="120"
            show-overflow-tooltip
          />
          <YdTableColumn prop="taskStatus" :label="$t('wf.taskStatus')" width="100" />
        </YdTable>
      </div>
      </YdSheetContent>
    </YdSheet>
  </Page>
</template>
